    /// The neighborhood publishes the same observation, and a focal that did not
    /// resolve names no language rather than borrowing one, so the
    /// focal-not-in-graph gap stays the limiting factor a reader is handed.
    #[test]
    fn an_empty_neighborhood_publishes_the_scope_it_walked() {
        // No language server at all, which is the container the v0.5.42
        // stranger run used.
        let _host = crate::edge_coverage::test_support::scoped_language_servers(&[]);
        let store = InMemoryGraph::new();
        let focal = make_entity_in(
            LanguageId::JavaScript,
            "createETagGenerator",
            "lib/utils.js",
        );
        let focal_id = focal.id;
        store.upsert_entity(&focal).unwrap();

        let mut args = HashMap::new();
        args.insert(
            "entity_id".to_string(),
            serde_json::json!(focal_id.to_string()),
        );
        args.insert("direction".to_string(), serde_json::json!("in"));
        let walked = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());
        assert_eq!(walked["relation_count"], 0);
        let coverage = &walked[crate::edge_coverage::EDGE_COVERAGE_KEY];
        assert_eq!(coverage["language"], "JavaScript");
        // `no_language_server` rather than `unsupported`: this build wires a
        // JavaScript adapter now, so what leaves the program unresolved is the
        // host, not the build. Both block certification, and the difference is
        // whether an operator can do anything about it.
        assert_eq!(coverage["reference_enrichment"], "no_language_server");
        assert!(
            coverage.get("scope_entities").is_none(),
            "a walk counts no region, so it publishes no count: {coverage}"
        );
        let negative = crate::negative::negative_for(
            "graph_neighborhood",
            &walked,
            &ready_daemon_envelope(1),
            &[],
        )
        .expect("an empty walk carries a negative");
        assert_eq!(negative["safe_to_conclude_absent"], false);

        let mut missing = HashMap::new();
        missing.insert(
            "entity_id".to_string(),
            serde_json::json!(EntityId::new().to_string()),
        );
        let unresolved = parsed_response(&handle_graph_neighborhood(&missing, &store).unwrap());
        assert_eq!(
            unresolved[crate::edge_coverage::EDGE_COVERAGE_KEY]["language"],
            "no resolved language"
        );
        let negative = crate::negative::negative_for(
            "graph_neighborhood",
            &unresolved,
            &ready_daemon_envelope(1),
            &[],
        )
        .expect("an unresolved focal carries a negative");
        assert!(
            negative["trust_reason"]
                .as_str()
                .unwrap()
                .starts_with("focal_not_in_graph"),
            "the focal miss stays the limiting factor: {negative}"
        );
    }

    #[tokio::test]
    async fn derived_member_persisted_legacy_edges_remain_candidates_before_relink() {
        let source = "const app = {}; for (const key of ['get']) { app[key] = () => 1; }";
        let blobs_dir = tempfile::tempdir().unwrap();
        let hash = kin_blobs::BlobStore::new(blobs_dir.path().join("objects"))
            .unwrap()
            .write(source.as_bytes())
            .unwrap();
        let indexed = kin_index::IndexPipeline::new()
            .index_file_content_with_tests(&FilePathId::new("members.js"), source.as_bytes(), hash)
            .unwrap()
            .indexed_file;
        let candidate = indexed
            .entities
            .iter()
            .find(|e| e.name == "app.get")
            .unwrap();
        for representation in ["typed", "legacy", "malformed"] {
            let mut target = candidate.clone();
            if representation == "legacy" {
                let derivation = kin_model::entity_derivation(&target).unwrap().unwrap();
                target
                    .metadata
                    .extra
                    .remove(kin_model::derivation::ENTITY_DERIVATION_KEY);
                target.span = Some(derivation.generator);
                target.doc_summary =
                    Some("Derived from a loop over `names`; no literal `get` declaration".into());
            } else if representation == "malformed" {
                target.metadata.extra.insert(
                    kin_model::derivation::ENTITY_DERIVATION_KEY.into(),
                    serde_json::json!({"schema": "unknown"}),
                );
            }
            let graph = InMemoryGraph::new();
            let caller = make_entity_in(LanguageId::JavaScript, "caller", "caller.js");
            let ordinary = make_entity_in(LanguageId::JavaScript, "ordinary", "ordinary.js");
            for entity in [&target, &caller, &ordinary] {
                graph.upsert_entity(entity).unwrap();
            }
            let mut old_call = make_relation(caller.id, target.id, RelationKind::Calls);
            old_call.origin = match representation {
                "typed" => RelationOrigin::Manual,
                "malformed" => RelationOrigin::Lsp,
                _ => RelationOrigin::Parsed,
            };
            let mut old_override = make_relation(target.id, ordinary.id, RelationKind::Overrides);
            old_override.origin = RelationOrigin::Lsp;
            let ordinary_call = make_relation(caller.id, ordinary.id, RelationKind::Calls);
            for relation in [&old_call, &old_override, &ordinary_call] {
                graph.upsert_relation(relation).unwrap();
            }
            // Persist the pre-upgrade shape through the product snapshot format,
            // close it and reopen without a parser or linker ever visiting it.
            let dir = tempfile::tempdir().unwrap();
            let snapshot_path = dir.path().join("legacy.kndb");
            std::fs::write(&snapshot_path, graph.to_snapshot().to_bytes().unwrap()).unwrap();
            drop(graph);
            let snapshot = kin_db::storage::format::GraphSnapshot::from_bytes(
                &std::fs::read(&snapshot_path).unwrap(),
            )
            .unwrap();
            let graph = InMemoryGraph::from_snapshot_without_text_index(snapshot).unwrap();
            let raw = graph.get_all_relations_for_entity(&target.id).unwrap();
            assert!(raw
                .iter()
                .all(|r| r.confidence == 1.0 && r.evidence.is_empty()));
            assert!(raw.iter().all(|r| RelationResolution::of(r).is_proven()));
            let view = kin_index::relation_read::relations_for_read(&graph, &target.id).unwrap();
            assert_eq!(view.len(), 1, "{representation}");
            assert_eq!(view[0].kind, RelationKind::Calls);
            assert_eq!(view[0].confidence, 0.3);
            assert!(!RelationResolution::of(&view[0]).is_proven());
            assert!(kin_index::resolution::is_receiver_name_guess(&view[0]));
            let ordinary_view =
                kin_index::relation_read::relations_for_read(&graph, &ordinary.id).unwrap();
            assert_eq!(ordinary_view.len(), 1);
            assert_eq!(
                serde_json::to_value(&ordinary_view[0]).unwrap(),
                serde_json::to_value(&ordinary_call).unwrap()
            );
            // Explicit candidate evidence cannot be laundered by ordinary
            // endpoint records or a later language-server origin/confidence.
            let mut marked = ordinary_call.clone();
            marked.origin = RelationOrigin::Lsp;
            marked.evidence.push(RelationEvidence {
                parser_rule: Some(kin_model::derivation::DERIVED_MEMBER_CANDIDATE_RULE.into()),
                ..Default::default()
            });
            let mut marked_view = vec![marked];
            kin_index::relation_read::project_relations_for_read(&graph, &mut marked_view).unwrap();
            assert_eq!(marked_view[0].confidence, 0.3);
            assert!(kin_index::resolution::is_receiver_name_guess(
                &marked_view[0]
            ));
            let args = HashMap::from([("entity_id".into(), serde_json::json!(target.id))]);
            let refs = parsed_response(&handle_find_references(&args, &graph, None).await.unwrap());
            assert_eq!(refs["total_upstream"], 0, "{representation}: {refs}");
            assert_eq!(refs["candidates"].as_array().unwrap().len(), 1, "{refs}");
            assert_eq!(refs["candidates"][0]["resolution"], "name_only");
            assert!(
                !has_incoming_reference_edge(&graph, &target.id, &[RelationKind::Calls]).unwrap()
            );
            let bulk_args = HashMap::from([(
                "entity_ids".into(),
                serde_json::json!([target.id, ordinary.id]),
            )]);
            let bulk = parsed_response(&handle_bulk_check_references(&bulk_args, &graph).unwrap());
            let rows = bulk["results"].as_array().unwrap();
            let row = rows
                .iter()
                .find(|r| r["entity_id"] == serde_json::json!(target.id))
                .unwrap();
            assert!(row["has_references"].is_null(), "{representation}: {bulk}");
            assert_eq!(row["known_reference_count"], 0);
            assert_eq!(row["derived_candidate_count"], 1);
            assert_eq!(row["verdict_complete"], false);
            assert_eq!(row["reference_count_complete"], false);
            let control = rows
                .iter()
                .find(|r| r["entity_id"] == serde_json::json!(ordinary.id))
                .unwrap();
            assert_eq!(control["has_references"], true);
            assert_eq!(control["known_reference_count"], 1);
            assert_eq!(control["derived_candidate_count"], 0);
            // A semantic read neither rewrites history nor silently repairs the store.
            assert_eq!(
                serde_json::to_value(graph.get_all_relations_for_entity(&target.id).unwrap())
                    .unwrap(),
                serde_json::to_value(raw).unwrap()
            );
        }
    }

    #[test]
    fn bulk_check_references_compact_and_verbose_shapes() {
        let store = InMemoryGraph::new();
        let caller = make_entity("caller", "src/a.rs");
        let live = make_entity("live", "src/b.rs");
        let dead = make_entity("dead", "src/c.rs");
        let caller_id = caller.id;
        let live_id = live.id;
        let dead_id = dead.id;

        store.upsert_entity(&caller).unwrap();
        store.upsert_entity(&live).unwrap();
        store.upsert_entity(&dead).unwrap();

        store
            .upsert_relation(&make_relation(caller_id, live_id, RelationKind::Calls))
            .unwrap();
        store
            .upsert_relation(&make_relation(caller_id, live_id, RelationKind::Imports))
            .unwrap();

        let mut args = HashMap::new();
        args.insert(
            "entity_ids".to_string(),
            serde_json::json!([live_id.to_string(), dead_id.to_string()]),
        );
        args.insert("relation_kind".to_string(), serde_json::json!("Any"));

        let compact = handle_bulk_check_references(&args, &store).unwrap();
        let body = parsed_response(&compact);
        assert_eq!(body["total_checked"], 2);
        assert_eq!(body["classified_count"], 1);
        assert_eq!(body["error_count"], 0);
        assert_eq!(body["incomplete_verdict_count"], 1);
        assert_eq!(body["with_references"], 1);
        assert_eq!(body["without_references"], 0);
        assert_eq!(body["compact"], true);
        let rows = body["results"].as_array().unwrap();
        assert_eq!(rows.len(), 2);
        let live_row = rows
            .iter()
            .find(|r| r["entity_id"] == serde_json::json!(live_id))
            .unwrap();
        assert_eq!(live_row["has_references"], true);
        assert!(live_row["reference_count"].is_null());
        // One caller holding a `Calls` and an `Imports` edge is one caller, as
        // `find_references` counts it. The batch counted edges and said 2.
        assert_eq!(live_row["known_reference_count"], 1);
        assert_eq!(live_row["counting_floor"], "import_scoped");
        assert_eq!(live_row["name_only_ceiling_kept"], 0);
        assert_eq!(live_row["reference_count_complete"], false);
        assert_eq!(live_row["verdict_complete"], true);
        assert!(
            live_row.get("name").is_none(),
            "compact mode must omit name"
        );
        let dead_row = rows
            .iter()
            .find(|r| r["entity_id"] == serde_json::json!(dead_id))
            .unwrap();
        assert!(
            dead_row["has_references"].is_null(),
            "a local-only zero is not a total reachability verdict"
        );
        assert!(dead_row["reference_count"].is_null());
        assert_eq!(dead_row["known_reference_count"], 0);
        assert_eq!(dead_row["reference_count_complete"], false);
        assert_eq!(dead_row["verdict_complete"], false);
        assert_eq!(
            dead_row["verdict_reason"],
            "cross-repo authority incomplete"
        );

        args.insert("compact".to_string(), serde_json::json!(false));
        let verbose = handle_bulk_check_references(&args, &store).unwrap();
        let vbody = parsed_response(&verbose);
        let vrows = vbody["results"].as_array().unwrap();
        let live_row = vrows
            .iter()
            .find(|r| r["entity_id"] == serde_json::json!(live_id))
            .unwrap();
        assert_eq!(live_row["name"], "live");
        assert_eq!(live_row["kind"], "Function");
        assert_eq!(live_row["file_path"], "src/b.rs");
        let matched = live_row["matched_kinds"].as_array().unwrap();
        assert!(matched.iter().any(|v| v == "calls"));
        assert!(matched.iter().any(|v| v == "imports"));
    }

    #[test]
    fn bulk_check_references_relation_kind_filter() {
        let store = InMemoryGraph::new();
        let caller = make_entity("caller", "src/a.rs");
        let target = make_entity("target", "src/b.rs");
        let caller_id = caller.id;
        let target_id = target.id;

        store.upsert_entity(&caller).unwrap();
        store.upsert_entity(&target).unwrap();
        store
            .upsert_relation(&make_relation(caller_id, target_id, RelationKind::Imports))
            .unwrap();

        let mut args = HashMap::new();
        args.insert(
            "entity_ids".to_string(),
            serde_json::json!([target_id.to_string()]),
        );

        // Asking for Calls only — Imports edge must NOT count.
        args.insert("relation_kind".to_string(), serde_json::json!("Calls"));
        let calls_resp = parsed_response(&handle_bulk_check_references(&args, &store).unwrap());
        assert_eq!(calls_resp["with_references"], 0);
        assert_eq!(calls_resp["without_references"], 0);
        assert!(calls_resp["results"][0]["has_references"].is_null());
        assert!(calls_resp["results"][0]["reference_count"].is_null());
        assert_eq!(calls_resp["results"][0]["known_reference_count"], 0);
        assert_eq!(calls_resp["results"][0]["reference_count_complete"], false);

        // Asking for Imports — should match.
        args.insert("relation_kind".to_string(), serde_json::json!("Imports"));
        let imports_resp = parsed_response(&handle_bulk_check_references(&args, &store).unwrap());
        assert_eq!(imports_resp["with_references"], 1);
        assert_eq!(imports_resp["results"][0]["has_references"], true);
        assert!(imports_resp["results"][0]["reference_count"].is_null());
        assert_eq!(imports_resp["results"][0]["known_reference_count"], 1);
        assert_eq!(
            imports_resp["results"][0]["reference_count_complete"],
            false
        );
    }

    #[test]
    fn bulk_check_references_rejects_empty_and_invalid() {
        let store = InMemoryGraph::new();

        let args = HashMap::new();
        let err = handle_bulk_check_references(&args, &store).unwrap_err();
        assert!(matches!(err, McpError::InvalidParams(_)));

        let mut empty = HashMap::new();
        empty.insert("entity_ids".to_string(), serde_json::json!([]));
        let err = handle_bulk_check_references(&empty, &store).unwrap_err();
        assert!(matches!(err, McpError::InvalidParams(_)));

        let mut bad = HashMap::new();
        bad.insert(
            "entity_ids".to_string(),
            serde_json::json!(["not-a-uuid", EntityId::new().to_string()]),
        );
        let resp = parsed_response(&handle_bulk_check_references(&bad, &store).unwrap());
        let rows = resp["results"].as_array().unwrap();
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["error"], "invalid entity_id (not a UUID)");
        assert_eq!(rows[1]["error"], "entity not found");
        assert_eq!(resp["classified_count"], 0);
        assert_eq!(resp["error_count"], 2);
        assert_eq!(resp["incomplete_verdict_count"], 0);
        assert_eq!(resp["with_references"], 0);
        assert_eq!(resp["without_references"], 0);
        for row in rows {
            assert!(
                row["has_references"].is_null(),
                "an invalid or missing entity is not a false reachability verdict: {row}"
            );
            assert!(row["reference_count"].is_null());
            assert!(row["known_reference_count"].is_null());
            assert_eq!(row["reference_count_complete"], false);
            assert_eq!(row["verdict_complete"], false);
        }
    }

    /// The focal of a reference reply is placed the way each row places its
    /// caller: by the dotted module that contains it, read from the graph's
    /// own module records. Without it, a reader who asks where the focal lives
    /// has only its projection to go on.
    #[tokio::test]
    async fn find_references_places_the_focal_and_its_caller_by_module() {
        let store = InMemoryGraph::new();
        let mut modules = Vec::new();
        for (name, unit) in [
            ("pkg", "pkg/__init__.py"),
            ("parsing", "pkg/parsing.py"),
            ("storage", "pkg/storage.py"),
        ] {
            let mut module = make_entity(name, unit);
            module.kind = EntityKind::Module;
            modules.push(module);
        }
        let target = make_entity("parse_note", "pkg/parsing.py");
        let caller = make_entity("ingest", "pkg/storage.py");
        let loose = make_entity("loose", "scripts/loose.py");
        for entity in modules.iter().chain([&target, &caller, &loose]) {
            store.upsert_entity(entity).unwrap();
        }
        store
            .upsert_relation(&make_relation(caller.id, target.id, RelationKind::Calls))
            .unwrap();
        store
            .upsert_relation(&make_relation(caller.id, loose.id, RelationKind::Calls))
            .unwrap();

        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(target.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(body["focal_entity"]["module"], "pkg.parsing", "{body:#}");
        let refs = body["references"].as_array().unwrap();
        assert_eq!(refs.len(), 1, "{body:#}");
        assert_eq!(refs[0]["module"], "pkg.storage", "{body:#}");

        // The receiver proof names its focal the same way.
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(target.id.to_string()),
            ),
            (
                "proof_for_caller".to_string(),
                serde_json::json!(caller.id.to_string()),
            ),
        ]);
        let proof = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(proof["focal_entity"]["module"], "pkg.parsing", "{proof:#}");
        assert_eq!(
            proof["receiver_proof"]["module"], "pkg.storage",
            "{proof:#}"
        );

        // A focal the graph records no module for carries none, as a row
        // does; nothing stands in for it.
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(loose.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert!(body["focal_entity"].get("module").is_none(), "{body:#}");
        assert_eq!(body["references"][0]["module"], "pkg.storage", "{body:#}");
    }

    #[tokio::test]
    async fn find_references_returns_only_graph_edges() {
        let store = InMemoryGraph::new();
        let caller = make_entity("caller", "src/a.rs");
        let target = make_entity("target", "src/b.rs");
        let caller_id = caller.id;
        let target_id = target.id;

        store.upsert_entity(&caller).unwrap();
        store.upsert_entity(&target).unwrap();
        store
            .upsert_relation(&make_relation(caller_id, target_id, RelationKind::Calls))
            .unwrap();

        let mut args = HashMap::new();
        args.insert(
            "entity_id".to_string(),
            serde_json::json!(target_id.to_string()),
        );

        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(body["total_upstream"], 1);
        let refs = body["references"].as_array().unwrap();
        assert_eq!(refs.len(), 1);
        assert_eq!(refs[0]["name"], "caller");
        assert_eq!(refs[0]["projection"]["path"], "src/a.rs");
        assert!(refs[0].get("file_path").is_none());
        assert!(refs[0].get("start_line").is_none());
        assert_eq!(refs[0]["kind"], "Function");
        // The keystone: each reference carries the caller's graph entity_id so an
        // agent can drill straight to its body with no name re-resolution.
        assert_eq!(refs[0]["entity_id"], caller_id.to_string());
        // Bodies are opt-in, so the default row carries neither the excerpt nor
        // the signature. `entity_id` above is what reaches the body.
        assert!(!refs[0].as_object().unwrap().contains_key("snippet"));
        assert!(!refs[0].as_object().unwrap().contains_key("signature"));

        args.insert("include_snippets".to_string(), serde_json::json!(true));
        let verbose = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        let verbose_refs = verbose["references"].as_array().unwrap();
        // Present in the shape when asked for (null here: the fixture has no
        // blob-backed body to project).
        assert!(verbose_refs[0].as_object().unwrap().contains_key("snippet"));
        assert_eq!(verbose_refs[0]["signature"], "fn caller()");
    }

    /// A Go declaration for the dispatch fixture, kind and signature named
    /// outright because both decide whether the walk answers.
    fn go_entity(kind: EntityKind, name: &str, file: &str, signature: &str) -> Entity {
        let mut entity = make_entity_in(LanguageId::Go, name, file);
        entity.kind = kind;
        entity.signature = signature.to_string();
        entity
    }

    /// The gh arrangement in miniature: one contract, one implementation of it,
    /// one type that misses a contract method, a caller written against the
    /// interface value and a caller written against the concrete type.
    ///
    /// Hand built, and the graph SHAPE it assumes is graded elsewhere:
    /// `kin-index/tests/go_interface_dispatch_candidates.rs` runs the real Go
    /// adapter over source and asserts that an interface's method specs are
    /// first-class `Interface.Method` entities the interface `Contains`. This
    /// test is about what `find_references` does with that shape, so it states
    /// it rather than re-deriving it, and if the adapter stops producing it that
    /// file is where it goes red.
    ///
    /// The `Calls` edge from `emit` is the one a language server produces:
    /// `sink.Write(p)` on an interface value resolves to the interface's method
    /// object, which is exactly what the Go compiler's own reference set does.
    fn go_dispatch_graph() -> (InMemoryGraph, Entity, Entity, Entity, Entity) {
        let store = InMemoryGraph::new();

        let writer = go_entity(
            EntityKind::Interface,
            "Writer",
            "internal/gh/contract.go",
            "type Writer interface",
        );
        let writer_write = go_entity(
            EntityKind::Method,
            "Writer.Write",
            "internal/gh/contract.go",
            "Write(p []byte) (int, error)",
        );
        let writer_close = go_entity(
            EntityKind::Method,
            "Writer.Close",
            "internal/gh/contract.go",
            "Close() error",
        );

        let buffer = go_entity(
            EntityKind::Class,
            "Buffer",
            "internal/buf/buffer.go",
            "type Buffer struct",
        );
        let buffer_write = go_entity(
            EntityKind::Method,
            "Buffer.Write",
            "internal/buf/buffer.go",
            "func (b *Buffer) Write(p []byte) (int, error)",
        );
        let buffer_close = go_entity(
            EntityKind::Method,
            "Buffer.Close",
            "internal/buf/buffer.go",
            "func (b *Buffer) Close() error",
        );

        // The control. `Counter` has a Write and no Close, so it satisfies no
        // Writer, and a method-name match alone must not carry it.
        let counter = go_entity(
            EntityKind::Class,
            "Counter",
            "internal/count/counter.go",
            "type Counter struct",
        );
        let counter_write = go_entity(
            EntityKind::Method,
            "Counter.Write",
            "internal/count/counter.go",
            "func (c *Counter) Write(p []byte) (int, error)",
        );

        let emit = go_entity(
            EntityKind::Function,
            "emit",
            "cmd/app/emit.go",
            "func emit(sink Writer, payload []byte) error",
        );
        let flush = go_entity(
            EntityKind::Function,
            "flush",
            "cmd/app/flush.go",
            "func flush(b *Buffer, payload []byte) error",
        );

        for entity in [
            &writer,
            &writer_write,
            &writer_close,
            &buffer,
            &buffer_write,
            &buffer_close,
            &counter,
            &counter_write,
            &emit,
            &flush,
        ] {
            store.upsert_entity(entity).unwrap();
        }
        for (owner, member) in [
            (&writer, &writer_write),
            (&writer, &writer_close),
            (&buffer, &buffer_write),
            (&buffer, &buffer_close),
            (&counter, &counter_write),
        ] {
            store
                .upsert_relation(&make_relation(owner.id, member.id, RelationKind::Contains))
                .unwrap();
        }

        // Through the interface value: the class this feature exists for.
        for spec in [&writer_write, &writer_close] {
            store
                .upsert_relation(&make_relation_with_site(
                    emit.id,
                    spec.id,
                    RelationKind::Calls,
                    "cmd/app/emit.go",
                    11,
                ))
                .unwrap();
        }
        // Straight at the concrete method: the proven direct call this answer
        // must keep reporting as proven.
        store
            .upsert_relation(&make_relation_with_site(
                flush.id,
                buffer_write.id,
                RelationKind::Calls,
                "cmd/app/flush.go",
                6,
            ))
            .unwrap();

        (store, buffer_write, counter_write, emit, flush)
    }

    /// The gap #63 closed on `kin refs` and left open here: a Go concrete method
    /// reached only through an interface value had NO direct callers, so this
    /// tool answered 0 for a method the repository calls. On the gh CLI that
    /// class is 184 call sites over 15 declarations.
    ///
    /// Both halves in one test on purpose. A candidate that appears is worth
    /// nothing if the proven call disappeared into the same list, and the
    /// distinction is the whole point: `references` is what the graph holds an
    /// edge for, `interface_dispatch.candidates` is what it does not.
    #[tokio::test]
    async fn a_method_reached_through_an_interface_is_a_candidate_and_a_direct_call_stays_proven() {
        let (store, buffer_write, _, emit, flush) = go_dispatch_graph();

        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(buffer_write.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        // The proven half, unchanged. One direct caller, counted, and carrying
        // no dispatch marker at all.
        assert_eq!(body["total_upstream"], 1, "{body}");
        assert_eq!(body["counts"]["referencing_entities"], 1);
        let references = body["references"].as_array().unwrap();
        assert_eq!(references.len(), 1);
        assert_eq!(references[0]["name"], "flush");
        assert_eq!(references[0]["entity_id"], flush.id.to_string());
        assert_eq!(references[0]["resolution"], "type_resolved");
        assert!(
            !references[0]
                .as_object()
                .unwrap()
                .contains_key(kin_index::dispatch::DISPATCH_FIELD),
            "a proven direct call must not be labelled a dispatch candidate: {}",
            references[0]
        );

        // The candidate half. Its own section, its own count, never added to
        // the headline above.
        let dispatch = &body[INTERFACE_DISPATCH_KEY];
        assert_eq!(dispatch["status"], "candidates_listed", "{dispatch}");
        assert_eq!(dispatch["contracts"], serde_json::json!(["Writer.Write"]));
        assert_eq!(dispatch["candidate_count"], 1);
        let candidates = dispatch["candidates"].as_array().unwrap();
        assert_eq!(candidates.len(), 1);
        assert_eq!(candidates[0]["name"], "emit");
        assert_eq!(candidates[0]["entity_id"], emit.id.to_string());
        assert_eq!(
            candidates[0][kin_index::dispatch::DISPATCH_FIELD],
            kin_index::dispatch::DISPATCH_INTERFACE_CANDIDATE
        );
        assert_eq!(
            candidates[0]["dispatch_via"],
            serde_json::json!(["Writer.Write"]),
            "the row names the contract it came through so a reader can check the claim"
        );
        // The evidence span the call edge carries survives the candidate path,
        // which is what makes a candidate checkable rather than a name: the
        // call to the CONTRACT is a real site the graph recorded.
        assert_eq!(
            candidates[0]["site_count"], 1,
            "the interface call site travels with the candidate: {}",
            candidates[0]
        );
        assert!(candidates[0]["sites_absent_reason"].is_null());

        // The count stays a count of proven edges, and says so.
        assert_eq!(body["counts"]["interface_dispatch_candidates"], 1);
        assert_eq!(
            body["counts"]["upstream_including_unconfirmed"], 2,
            "the ceiling includes the candidate; the headline does not"
        );

        // An absence gate that certified this answer would be certifying an
        // absence the response itself contradicts.
        let degradations = body["degradations"].as_array().unwrap();
        assert!(
            degradations.iter().any(|entry| {
                entry["reason"] == INTERFACE_DISPATCH_CANDIDATES_REASON
                    && entry["component"] == CALL_RESOLUTION_COMPONENT
            }),
            "the held-out rows must be disclosed where the absence gate reads them: {body}"
        );
    }

    /// Every row-bearing list a `find_references` reply carries, named against
    /// the response budget's own shape table.
    ///
    /// A list is row-bearing when its entries are entity rows, and that is what
    /// ties this to the defect: a list of entity rows grows with the repository,
    /// so one the budget cannot count is one that can take the answer's room.
    /// Lists of strings, line numbers and disclosure entries are bounded by the
    /// question rather than by the graph, and are not the hazard.
    fn unbudgeted_row_lists(body: &serde_json::Value) -> Vec<String> {
        let governed = crate::budget::governed_collections("find_references");
        let rows = |value: &serde_json::Value| -> bool {
            value
                .as_array()
                .is_some_and(|entries| entries.iter().any(|entry| entry.get("entity_id").is_some()))
        };
        let mut unbudgeted = Vec::new();
        let Some(top) = body.as_object() else {
            return unbudgeted;
        };
        for (key, value) in top {
            if rows(value) && !governed.contains(&key.as_str()) {
                unbudgeted.push(key.clone());
            }
            let Some(block) = value.as_object() else {
                continue;
            };
            for (inner, nested) in block {
                let path = format!("{key}.{inner}");
                if rows(nested) && !governed.contains(&path.as_str()) {
                    unbudgeted.push(path);
                }
            }
        }
        unbudgeted
    }

    /// This is the test that would have caught the defect.
    ///
    /// The shape table named `references` alone, so the answer was the only
    /// array the bounder could reach. A reply for `api/queries_repo.go:232` on
    /// the gh CLI then spent 57,323 characters on `interface_dispatch.candidates`
    /// and 39,607 on `candidates`, withheld two of its three real reference rows
    /// with `"reason": "response_budget"` to make room, and shipped 99,799
    /// characters against a 60,000 ceiling anyway.
    #[tokio::test]
    async fn every_row_list_a_reply_carries_is_one_the_budget_can_cut() {
        let (store, buffer_write, ..) = go_dispatch_graph();
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(buffer_write.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        // The fixture has to carry the nested list, or this passes by asserting
        // nothing about the key the defect was hiding behind.
        assert!(
            body[INTERFACE_DISPATCH_KEY]["candidates"]
                .as_array()
                .is_some_and(|rows| !rows.is_empty()),
            "the fixture must carry dispatch candidates: {body}"
        );
        assert!(
            !body["references"].as_array().unwrap().is_empty(),
            "the fixture must carry an answer to protect: {body}"
        );
        assert_eq!(
            unbudgeted_row_lists(&body),
            Vec::<String>::new(),
            "these lists grow with the repository and the response budget cannot reach them, \
             so they can take the answer's room: {body}"
        );
    }

    /// The control the section is worth nothing without, and the control on the
    /// control. A type that misses one contract method satisfies nothing, and
    /// the section still answers, because a section that appears only when it
    /// has rows is one the reader who needs it never learns to look for.
    #[tokio::test]
    async fn a_go_method_that_satisfies_no_interface_still_gets_the_section_at_zero() {
        let (store, _, counter_write, _, _) = go_dispatch_graph();

        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(counter_write.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        assert_eq!(body["total_upstream"], 0);
        let dispatch = &body[INTERFACE_DISPATCH_KEY];
        assert_eq!(dispatch["status"], "satisfies_no_interface", "{dispatch}");
        assert_eq!(dispatch["candidate_count"], 0);
        assert_eq!(body["counts"]["interface_dispatch_candidates"], 0);
        // Nothing was held back, so nothing is disclosed and the absence gate
        // is left exactly as it was.
        assert!(
            body.get("degradations").is_none_or(|entries| {
                entries.as_array().is_none_or(|entries| {
                    !entries
                        .iter()
                        .any(|entry| entry["reason"] == INTERFACE_DISPATCH_CANDIDATES_REASON)
                })
            }),
            "a zero section must not file a degradation: {body}"
        );
    }

    /// A focal with no dispatch story carries no block, so every answer on every
    /// other language is byte-identical to the one before this existed.
    #[tokio::test]
    async fn a_focal_with_no_dispatch_story_carries_no_dispatch_block() {
        let store = InMemoryGraph::new();
        let caller = make_entity("caller", "src/a.rs");
        let target = make_entity("target", "src/b.rs");
        store.upsert_entity(&caller).unwrap();
        store.upsert_entity(&target).unwrap();
        store
            .upsert_relation(&make_relation(caller.id, target.id, RelationKind::Calls))
            .unwrap();

        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(target.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(body["total_upstream"], 1);
        assert!(
            body.get(INTERFACE_DISPATCH_KEY).is_none(),
            "a Rust function has no interface-dispatch question: {body}"
        );
        assert!(
            body["counts"]
                .get("interface_dispatch_candidates")
                .is_none(),
            "and the counts block must not answer one either: {body}"
        );
    }

    /// An interface method's own callers are already direct callers, so asking
    /// what dispatch reaches `Writer.Write` is describing a contract as an
    /// implementation of itself. No block, and the direct caller still lands.
    #[tokio::test]
    async fn an_interface_method_spec_carries_no_dispatch_block() {
        let (store, _, _, emit, _) = go_dispatch_graph();
        let spec = store
            .query_entities(&EntityFilter::default())
            .unwrap()
            .into_iter()
            .find(|entity| entity.name == "Writer.Write")
            .expect("the fixture holds the contract's method spec");

        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(spec.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(body["total_upstream"], 1);
        assert_eq!(body["references"][0]["entity_id"], emit.id.to_string());
        assert!(
            body.get(INTERFACE_DISPATCH_KEY).is_none(),
            "the contract is not dispatched to itself: {body}"
        );
    }

    /// The dispatch fixture with declaration spans, so a row that claims to
    /// carry a line can be checked against one.
    ///
    /// Returns the interface's `Write` spec and the concrete `Buffer.Write` it
    /// is satisfied by, which is the pair every assertion below is about.
    fn go_implementations_graph() -> (InMemoryGraph, Entity, Entity) {
        let (store, buffer_write, _counter_write, _emit, _flush) = go_dispatch_graph();
        let spec = store
            .query_entities(&EntityFilter::default())
            .unwrap()
            .into_iter()
            .find(|entity| entity.name == "Writer.Write")
            .expect("the fixture holds the contract's Write spec");

        // Spans the hand-built fixture leaves unset. `Buffer.Write` is declared
        // on line 8 of its file, which reads back as 8 through the same 1-based
        // presentation `list_file_entities` uses, so a caller who resolved an
        // entity by line resolves this row back to the same one.
        let mut located = buffer_write.clone();
        located.span = Some(kin_model::SourceSpan {
            file: FilePathId::new("internal/buf/buffer.go"),
            start_byte: 0,
            end_byte: 1,
            start_line: 7,
            start_col: 0,
            end_line: 10,
            end_col: 1,
        });
        store.upsert_entity(&located).unwrap();
        (store, spec, located)
    }

    /// The finding this closes, at the surface a caller reaches for.
    ///
    /// Measured on `cli/cli` at `14d339d9` with published 0.7.20: asked where an
    /// interface method is implemented, Kin returned zero correct
    /// implementation sites out of 142 across 75 queries, against a one-line
    /// grep that returned every one. It named the implementing TYPE and the file
    /// it lives in and never the implementing method's line, because
    /// `graph_neighborhood` answered at file granularity in every direction.
    ///
    /// The declaration's id is the assertion. A file-granularity answer is what
    /// scored zero, and the id is the declaration's own address; the block
    /// serves its file only as the projection it is, and no file line.
    #[test]
    fn graph_neighborhood_names_where_an_interface_method_is_implemented() {
        let (store, spec, buffer_write) = go_implementations_graph();
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(spec.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("in")),
            ("depth".to_string(), serde_json::json!(1)),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());

        let block = &body[INTERFACE_IMPLEMENTATIONS_KEY];
        assert_eq!(block["status"], "candidates", "{body}");
        assert_eq!(block["candidate_count"], 1, "{body}");
        let row = &block["candidates"][0];
        assert_eq!(row["name"], "Buffer.Write");
        assert_eq!(row["receiver"], "Buffer");
        assert_eq!(
            row["projection"],
            serde_json::json!({ "path": "internal/buf/buffer.go" }),
            "{body}"
        );
        for gone in ["file_path", "line", "start_line"] {
            assert!(
                row.get(gone).is_none(),
                "an implementation row carries no file address, so {gone} must be absent: {body}"
            );
        }
        assert_eq!(row["implements"], IMPLEMENTS_INTERFACE_CANDIDATE);
        assert_eq!(
            row["entity_id"],
            buffer_write.id.to_string(),
            "the declaration's id is the answer; the file alone is what scored zero: {body}"
        );

        // And among the neighbors, because a reader walking `entities` must not
        // have to know about a second key to see the answer.
        let listed = body["entities"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entity| entity["name"] == "Buffer.Write")
            .unwrap_or_else(|| panic!("the implementation is one of the neighbors: {body}"));
        assert_eq!(listed["line"], 8);
        assert_eq!(listed["implements"], IMPLEMENTS_INTERFACE_CANDIDATE);
    }

    /// A change to an interface method's signature has to be made in every
    /// method that implements it, and Go records no edge for an
    /// implementation, so `affected_overrides` holds none. Measured on gin:
    /// `impact` on `Core.MarshalIndent` said 0 methods implement it while
    /// five codecs do. The answer lists the method-set candidates beside the
    /// overrides, marked as candidates, and names them on its answer line.
    #[tokio::test]
    async fn impact_on_an_interface_method_lists_the_methods_that_implement_it() {
        let (store, spec, buffer_write) = go_implementations_graph();
        // The package the implementation is declared in, which places its row.
        let mut package = go_entity(
            EntityKind::Module,
            "buf",
            "internal/buf/buffer.go",
            "package buf",
        );
        package.span = buffer_write.span.clone();
        store.upsert_entity(&package).unwrap();
        let sessions = crate::session::SessionRegistry::empty_for_test();
        let result = crate::handlers::review::handle_impact_analysis(
            &HashMap::from([
                (
                    "entity_ids".to_string(),
                    serde_json::json!([spec.id.to_string()]),
                ),
                ("include_traffic".to_string(), serde_json::json!(false)),
            ]),
            &store,
            &sessions,
        )
        .await
        .unwrap();
        let body = parsed_response(&result);
        let rows = body[crate::impact_sections::INTERFACE_IMPLEMENTATIONS_KEY]
            .as_array()
            .unwrap_or_else(|| panic!("the implementations are listed: {body}"));
        assert_eq!(rows.len(), 1, "{body}");
        assert_eq!(rows[0]["id"], buffer_write.id.to_string(), "{body}");
        assert_eq!(rows[0]["name"], "Buffer.Write", "{body}");
        assert_eq!(
            rows[0]["resolution"], IMPLEMENTS_INTERFACE_CANDIDATE,
            "{body}"
        );
        // Written like every other impact row: the entity's own kind, its
        // role, which a reader leaving test code out drops a row by, and the
        // module that places it.
        assert_eq!(rows[0]["kind"], "method", "{body}");
        assert_eq!(rows[0]["role"], "source", "{body}");
        assert!(
            rows[0]["module"]
                .as_str()
                .is_some_and(|module| module.ends_with("buf")),
            "{body}"
        );
        assert!(
            body[crate::impact_sections::INTERFACE_IMPLEMENTATIONS_NOTE_KEY]
                .as_str()
                .is_some_and(|note| note.contains("not a recorded one")),
            "{body}"
        );
        // A concrete method is no contract, and gets no such list.
        let result = crate::handlers::review::handle_impact_analysis(
            &HashMap::from([
                (
                    "entity_ids".to_string(),
                    serde_json::json!([buffer_write.id.to_string()]),
                ),
                ("include_traffic".to_string(), serde_json::json!(false)),
            ]),
            &store,
            &sessions,
        )
        .await
        .unwrap();
        let body = parsed_response(&result);
        assert!(
            body.get(crate::impact_sections::INTERFACE_IMPLEMENTATIONS_KEY)
                .is_none(),
            "{body}"
        );
    }

    /// A test fake that satisfies an interface is test code like any other:
    /// an impact answer that leaves test code out leaves it out of the
    /// implementations too, and counts it among what it left out.
    #[tokio::test]
    async fn impact_leaves_a_test_implementation_out_with_the_rest_of_test_code() {
        let (store, spec, buffer_write) = go_implementations_graph();
        let mut fake = buffer_write.clone();
        fake.role = kin_model::EntityRole::Test;
        store.upsert_entity(&fake).unwrap();
        let sessions = crate::session::SessionRegistry::empty_for_test();
        let impact = |include_tests: bool| {
            let store = &store;
            let sessions = &sessions;
            let spec = spec.id.to_string();
            async move {
                let result = crate::handlers::review::handle_impact_analysis(
                    &HashMap::from([
                        ("entity_ids".to_string(), serde_json::json!([spec])),
                        ("include_traffic".to_string(), serde_json::json!(false)),
                        (
                            "include_tests".to_string(),
                            serde_json::json!(include_tests),
                        ),
                    ]),
                    store,
                    sessions,
                )
                .await
                .unwrap();
                parsed_response(&result)
            }
        };
        let with_tests = impact(true).await;
        let rows = with_tests[crate::impact_sections::INTERFACE_IMPLEMENTATIONS_KEY]
            .as_array()
            .unwrap_or_else(|| panic!("the fake is listed with test code: {with_tests}"));
        assert_eq!(rows.len(), 1, "{with_tests}");
        assert_eq!(rows[0]["role"], "test", "{with_tests}");

        let without = impact(false).await;
        assert!(
            without[crate::impact_sections::INTERFACE_IMPLEMENTATIONS_KEY]
                .as_array()
                .is_none_or(|rows| rows.is_empty()),
            "{without}"
        );
        assert_eq!(
            without[crate::handlers::review::IMPACT_TESTS_EXCLUDED_KEY]["entities"],
            1,
            "{without}"
        );
    }

    /// The control. A type that misses one contract method is not an
    /// implementation, which is exactly the mistake the one-line grep makes and
    /// pays for in precision.
    #[test]
    fn graph_neighborhood_does_not_name_a_type_that_misses_a_contract_method() {
        let (store, spec, _) = go_implementations_graph();
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(spec.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("in")),
            ("depth".to_string(), serde_json::json!(1)),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());
        let named = serde_json::to_string(&body[INTERFACE_IMPLEMENTATIONS_KEY]).unwrap();
        assert!(
            !named.contains("Counter.Write"),
            "Counter has no Close, so it implements nothing here: {named}"
        );
    }

    /// An outgoing walk is asking what the contract depends on. Implementations
    /// stand behind it, not in front of it, so the section does not appear and
    /// every existing `direction: out` response stays byte-identical.
    #[test]
    fn graph_neighborhood_out_does_not_answer_the_implementations_question() {
        let (store, spec, _) = go_implementations_graph();
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(spec.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("out")),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());
        assert!(body.get(INTERFACE_IMPLEMENTATIONS_KEY).is_none(), "{body}");
    }

    /// A focal with no implementations story at all gets no section, so a Rust
    /// function's neighborhood is unchanged and a reader never learns to read a
    /// section that means nothing where they found it.
    #[test]
    fn graph_neighborhood_leaves_a_non_contract_focal_alone() {
        let (store, _spec, buffer_write) = go_implementations_graph();
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(buffer_write.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("in")),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());
        assert!(
            body.get(INTERFACE_IMPLEMENTATIONS_KEY).is_none(),
            "a concrete method is an implementation, not a contract: {body}"
        );
    }

    /// `find_references` answers the same question, in its own block, and does
    /// not move one row of the answer it already gave.
    ///
    /// The dispatch half of this document's measurement is a Kin win that rests
    /// on `references` holding exactly the sites that dispatch through the
    /// contract. A method declaration is not one of those sites, so folding
    /// implementations into `references` would buy this axis by selling that
    /// one.
    #[tokio::test]
    async fn find_references_answers_implementations_without_moving_its_references() {
        let (store, spec, buffer_write) = go_implementations_graph();
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(spec.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        let block = &body[INTERFACE_IMPLEMENTATIONS_KEY];
        assert_eq!(block["status"], "candidates", "{body}");
        assert_eq!(block["candidates"][0]["name"], "Buffer.Write");
        assert_eq!(
            block["candidates"][0]["entity_id"],
            buffer_write.id.to_string(),
            "{body}"
        );
        assert_eq!(
            block["candidates"][0]["projection"]["path"], "internal/buf/buffer.go",
            "{body}"
        );
        assert!(
            block["candidates"][0].get("line").is_none(),
            "no file line on a find_references row of any kind: {body}"
        );

        // The dispatch answer, untouched. `emit` calls the contract and the
        // implementation is not among the rows or the count.
        assert_eq!(body["total_upstream"], 1, "{body}");
        let referenced: Vec<&str> = body["references"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["name"].as_str().unwrap())
            .collect();
        assert_eq!(referenced, vec!["emit"]);
        assert!(
            !referenced.contains(&"Buffer.Write"),
            "an implementation is not a reference to the contract it satisfies: {body}"
        );
        assert!(
            !serde_json::to_string(&body["candidates"])
                .unwrap()
                .contains(&buffer_write.id.to_string()),
            "nor a same-name reference candidate: {body}"
        );
    }

    /// Asked about a method, `find_references` names what overrides it beside
    /// the callers and never among them.
    ///
    /// The measured miss: "which functions must change if
    /// `SessionInterface.open_session` gains a required parameter" answered the
    /// two callers and none of the three overrides, one of which sat in the
    /// same file with its `Overrides` edge already in the graph.
    #[tokio::test]
    async fn find_references_lists_overrides_of_a_method_outside_its_references() {
        let store = InMemoryGraph::new();
        let base = make_method_in(
            LanguageId::Python,
            "SessionInterface.open_session",
            "src/flask/sessions.py",
        );
        let secure = make_method_in(
            LanguageId::Python,
            "SecureCookieSessionInterface.open_session",
            "src/flask/sessions.py",
        );
        let nested = make_method_in(
            LanguageId::Python,
            "test_session_error_pops_context.<locals>.FailingSessionInterface.open_session",
            "tests/test_reqctx.py",
        );
        let caller = make_method_in(
            LanguageId::Python,
            "AppContext._get_session",
            "src/flask/ctx.py",
        );
        for entity in [&base, &secure, &nested, &caller] {
            store.upsert_entity(entity).unwrap();
        }
        for relation in [
            make_relation(secure.id, base.id, RelationKind::Overrides),
            make_relation(nested.id, base.id, RelationKind::Overrides),
            make_relation_with_site(
                caller.id,
                base.id,
                RelationKind::Calls,
                "src/flask/ctx.py",
                3,
            ),
        ] {
            store.upsert_relation(&relation).unwrap();
        }
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(base.id.to_string()),
        )]);
        let mut body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        let block = &body[super::super::overrides::OVERRIDDEN_BY_KEY];
        assert_eq!(block["count"], 2, "{body}");
        let overriders: Vec<&str> = block["overriders"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["name"].as_str().unwrap())
            .collect();
        assert_eq!(
            overriders,
            vec![
                "SecureCookieSessionInterface.open_session",
                "test_session_error_pops_context.<locals>.FailingSessionInterface.open_session",
            ]
        );
        assert!(block["overriders"]
            .as_array()
            .unwrap()
            .iter()
            .all(|row| row.get("line").is_none() && row["resolution"] == "type_resolved"));
        // The references are the callers alone, and the count is theirs.
        let referenced: Vec<&str> = body["references"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["name"].as_str().unwrap())
            .collect();
        assert_eq!(referenced, vec!["AppContext._get_session"], "{body}");
        assert_eq!(body["total_upstream"], 1, "{body}");

        // The block rides an answer-only reply.
        project_answer_only(&mut body);
        assert_eq!(
            body[super::super::overrides::OVERRIDDEN_BY_KEY]["count"],
            2,
            "{body}"
        );

        // An override asked about has no overrides of its own to list, and
        // still says so.
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(secure.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(
            body[super::super::overrides::OVERRIDDEN_BY_KEY]["count"],
            0,
            "{body}"
        );
    }

    /// A contract nothing satisfies answers none, at zero, and says which fact
    /// it is reporting. A section that appears only when it has rows is one no
    /// reader learns to look for, and the reader who most needs this one is the
    /// reader deciding whether a contract is dead.
    #[test]
    fn graph_neighborhood_answers_the_implementations_question_at_zero() {
        let store = InMemoryGraph::new();
        let writer = go_entity(
            EntityKind::Interface,
            "Writer",
            "internal/gh/contract.go",
            "type Writer interface",
        );
        let spec = go_entity(
            EntityKind::Method,
            "Writer.Write",
            "internal/gh/contract.go",
            "Write(p []byte) (int, error)",
        );
        for entity in [&writer, &spec] {
            store.upsert_entity(entity).unwrap();
        }
        store
            .upsert_relation(&make_relation(writer.id, spec.id, RelationKind::Contains))
            .unwrap();

        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(spec.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("in")),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());
        let block = &body[INTERFACE_IMPLEMENTATIONS_KEY];
        assert_eq!(block["status"], "no_implementation", "{body}");
        assert_eq!(block["candidate_count"], 0);
        assert_eq!(block["interface"], "Writer");
        // No implementation is no file, stated rather than left absent, so a
        // reader asking the file question is answered at zero instead of being
        // pushed back to `entities` to project one for themselves.
        assert_eq!(block["file_count"], 0, "{body}");
        assert_eq!(block["files"], serde_json::json!([]), "{body}");
    }

    /// The second half of the same finding, at the same surface.
    ///
    /// Measured on `cli/cli` at `14d339d9` against the same compiler gold that
    /// graded the site axis, over the same 75 replies: the implementation SITES
    /// came back at precision 0.9216, and the implementation FILES at precision
    /// 0.1334, 812 false-positive files against 125 true ones. 800 of those 812
    /// were named by a row carrying no position at all, because the only
    /// file-granularity answer the reply offered was `entities`, and an incoming
    /// walk around a contract is the set of things that CALL it. On the pooled
    /// collision strata the published headline reports the same pair as F1
    /// 0.9469 and 0.2286.
    ///
    /// So the assertion is a pair. `emit` calls the contract and its file is in
    /// the walk; it must not be in the implementation files. The file answer is
    /// the files the rows above it are declared in, and nothing else.
    #[test]
    fn graph_neighborhood_names_the_files_an_interface_method_is_implemented_in() {
        let (store, spec, _buffer_write) = go_implementations_graph();
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(spec.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("in")),
            ("depth".to_string(), serde_json::json!(1)),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());

        let block = &body[INTERFACE_IMPLEMENTATIONS_KEY];
        assert_eq!(block["status"], "candidates", "{body}");
        assert_eq!(
            block["files"],
            serde_json::json!(["internal/buf/buffer.go"]),
            "the files the candidates are declared in and no others: {body}"
        );
        assert_eq!(block["file_count"], 1, "{body}");

        // The neighborhood really does name the caller's file, which is why
        // projecting it was wrong and why this block has to answer instead.
        let walked: Vec<&str> = body["entities"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|entity| entity["file_path"].as_str())
            .collect();
        assert!(
            walked.contains(&"cmd/app/emit.go"),
            "the fixture's caller is in the walk, or this test is not about the finding: {body}"
        );
        let answered: Vec<&str> = block["files"]
            .as_array()
            .unwrap()
            .iter()
            .map(|file| file.as_str().unwrap())
            .collect();
        assert!(
            !answered.contains(&"cmd/app/emit.go"),
            "a caller's file is where the contract is USED, not where it is implemented: {body}"
        );
        // Nor the contract's own file, which every one of those 75 queries also
        // carried, because the focal is part of its own neighborhood.
        assert!(
            !answered.contains(&"internal/gh/contract.go"),
            "the declaration's own file is not an implementation of it: {body}"
        );
    }

    /// The file answer is the site answer, read at a coarser granularity. It is
    /// derived from the rows rather than collected beside them, so there is no
    /// arrangement of this graph in which the two disagree.
    #[test]
    fn interface_implementation_files_are_exactly_the_files_of_its_candidates() {
        let (store, spec, _) = go_implementations_graph();
        let args = HashMap::from([
            (
                "entity_id".to_string(),
                serde_json::json!(spec.id.to_string()),
            ),
            ("direction".to_string(), serde_json::json!("in")),
        ]);
        let body = parsed_response(&handle_graph_neighborhood(&args, &store).unwrap());
        let block = &body[INTERFACE_IMPLEMENTATIONS_KEY];

        let mut from_rows: Vec<&str> = block["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|row| row["projection"]["path"].as_str())
            .collect();
        assert!(!from_rows.is_empty(), "{body}");
        from_rows.sort_unstable();
        from_rows.dedup();
        let answered: Vec<&str> = block["files"]
            .as_array()
            .unwrap()
            .iter()
            .map(|file| file.as_str().unwrap())
            .collect();
        assert_eq!(answered, from_rows, "{body}");
    }

    /// `limit` truncates `entities`; it does not truncate the answer.
    ///
    /// A reader who projected `entities` to paths got a file answer that shrank
    /// with the walk's page size. This one is computed from the whole candidate
    /// set before any of that, so the same question gets the same answer at
    /// `limit: 1` as at `limit: 200`.
    #[test]
    fn interface_implementation_files_survive_the_entity_limit() {
        let (store, spec, _) = go_implementations_graph();
        let answer_at = |limit: u64| {
            let args = HashMap::from([
                (
                    "entity_id".to_string(),
                    serde_json::json!(spec.id.to_string()),
                ),
                ("direction".to_string(), serde_json::json!("in")),
                ("limit".to_string(), serde_json::json!(limit)),
            ]);
            parsed_response(&handle_graph_neighborhood(&args, &store).unwrap())
        };

        let clipped = answer_at(1);
        assert_eq!(clipped["truncated"], true, "{clipped}");
        assert_eq!(clipped["entities"].as_array().unwrap().len(), 1);
        assert_eq!(
            clipped[INTERFACE_IMPLEMENTATIONS_KEY]["files"],
            serde_json::json!(["internal/buf/buffer.go"]),
            "the answer is not a page of the walk: {clipped}"
        );
        assert_eq!(
            clipped[INTERFACE_IMPLEMENTATIONS_KEY]["files"],
            answer_at(200)[INTERFACE_IMPLEMENTATIONS_KEY]["files"]
        );
    }

    /// Both surfaces answer the file question, with the same files.
    ///
    /// They share one derivation for the reason they share the block: a reader
    /// who asks `find_references` where a contract is implemented and a reader
    /// who walks its neighborhood are asking the same question, and two answers
    /// to it would be one answer too many.
    #[tokio::test]
    async fn find_references_names_the_same_implementation_files() {
        let (store, spec, _) = go_implementations_graph();
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(spec.id.to_string()),
        )]);
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        let block = &body[INTERFACE_IMPLEMENTATIONS_KEY];
        assert_eq!(
            block["files"],
            serde_json::json!(["internal/buf/buffer.go"]),
            "{body}"
        );
        assert_eq!(block["file_count"], 1, "{body}");

        // And the reference rows, which answer the other question, still name
        // the caller's file. The two answers are different on purpose.
        let referenced: Vec<&str> = body["references"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|row| row["projection"]["path"].as_str())
            .collect();
        assert!(referenced.contains(&"cmd/app/emit.go"), "{body}");
    }

    /// The ambiguity counter alone cannot count ambiguity on any language
    /// that qualifies a method name, which is most of them, and even naming
    /// the count could only ever describe one winner and discard the other
    /// candidates' own reference lists.
    ///
    /// Measured on pallets/flask at d318b683 with npm `@kinlab/kin@0.5.42`:
    /// `find_references(query: "dispatch_request")` resolved
    /// `Flask.dispatch_request` and reported `same_name_candidates: 1`, while
    /// `semantic_search` for the same string in the same session returned
    /// `total_matches: 6`. Three of those are source-role methods whose
    /// unqualified name is exactly `dispatch_request`, in two files.
    ///
    /// The original count bug is fixed elsewhere (the count is taken against
    /// what the CALLER typed, not the resolved focal's qualified name, and by
    /// the same pattern rule the resolver ranked with). This is the sharper
    /// fix on top of it: rather than count three candidates and still answer
    /// for only one, `find_references` now sections a full reply for each of
    /// the three under `candidates_by_owner`, labelled by its own
    /// owner-qualified name. `find_references_reports_an_ambiguous_name_resolution`
    /// beside this test is the whole-name case, two unqualified functions with
    /// one name, which is sectioned the same way.
    #[tokio::test]
    async fn find_references_counts_what_the_query_could_have_meant() {
        let store = InMemoryGraph::new();
        let app = make_method_in(
            LanguageId::Python,
            "Flask.dispatch_request",
            "src/flask/app.py",
        );
        let base = make_method_in(
            LanguageId::Python,
            "View.dispatch_request",
            "src/flask/views.py",
        );
        let derived = make_method_in(
            LanguageId::Python,
            "MethodView.dispatch_request",
            "src/flask/views.py",
        );
        for entity in [&app, &base, &derived] {
            store.upsert_entity(entity).unwrap();
        }

        // The control. Three distinct entities really do answer to this query in
        // this store, so a response reporting fewer is reporting a fact the
        // store contradicts rather than a small repository.
        let matched = store
            .query_entities(&kin_model::graph::EntityFilter {
                name_pattern: Some("dispatch_request".to_string()),
                ..Default::default()
            })
            .unwrap();
        assert_eq!(
            matched.len(),
            3,
            "control: the query must be genuinely ambiguous in this store, or this test \
             cannot fail"
        );

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("dispatch_request"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        assert_eq!(
            body["ambiguous_focal"], true,
            "three owner-qualified entities share this bare name, so the answer must say so: \
             {body}"
        );
        assert_eq!(
            body["candidate_count"], 3,
            "the count must answer what the QUERY could have meant, not how many entities \
             carry any one winner's qualified name: {body}"
        );
        assert!(
            body.get("focal_entity").is_none()
                && body.get("references").is_none()
                && body.get("total_upstream").is_none(),
            "a sectioned answer names no single winner at the top level: {body}"
        );

        // Every candidate gets its own labelled, full section rather than being
        // rejected and reduced to an id a caller could look up.
        let sections = body[AMBIGUOUS_CANDIDATES_KEY]
            .as_array()
            .unwrap_or_else(|| panic!("an ambiguous resolution must section every match: {body}"));
        assert_eq!(sections.len(), 3, "{body}");
        let mut owner_qualified_names: Vec<&str> = sections
            .iter()
            .map(|section| {
                section["owner_qualified_name"]
                    .as_str()
                    .unwrap_or_else(|| panic!("every section must label itself: {section}"))
            })
            .collect();
        owner_qualified_names.sort_unstable();
        assert_eq!(
            owner_qualified_names,
            vec![
                "Flask.dispatch_request",
                "MethodView.dispatch_request",
                "View.dispatch_request",
            ],
            "every candidate is labelled by its own owner-qualified name, none dropped, none \
             merged into another's section: {body}"
        );
        for section in sections {
            let label = section["owner_qualified_name"].as_str().unwrap();
            assert_eq!(
                section["focal_entity"]["name"], label,
                "a section's own focal_entity must be the entity its label names: {section}"
            );
            assert!(
                section["references"].is_array() && section["total_upstream"].is_number(),
                "a section carries a single-focal reply's own fields: {section}"
            );
        }

        // The ambiguity is named, with how many candidates, and because every
        // one of them was answered for it is a settled resolution rather than
        // a degradation.
        assert_eq!(
            body["focal_resolution"]["same_name_candidates"], 3,
            "{body}"
        );
        assert_eq!(body["focal_resolution"]["sectioned"], 3, "{body}");
        assert!(
            body["focal_resolution"]["detail"]
                .as_str()
                .is_some_and(|detail| detail.contains('3')),
            "the ambiguity must be named, with how many candidates: {body}"
        );
        assert!(body.get("degradations").is_none(), "{body}");

        // The verdict half of this, each section graded as its own answer and
        // the response's verdict composed from theirs, is asserted through the
        // envelope in `same_name_tests`. This handler returns its payload
        // before the envelope layer attaches one.
    }

    /// The control for the case above, and the reason the field cannot simply be
    /// redefined as "everything the pattern matched". Addressing by entity_id
    /// resolves nothing by name, so there is no query ambiguity to report, and
    /// the count must stay the exact-name twin count that protects the cfg-twin
    /// shape rather than inheriting a substring's fan-out.
    #[tokio::test]
    async fn find_references_addressed_by_id_counts_exact_name_twins() {
        let store = InMemoryGraph::new();
        let app = make_method_in(
            LanguageId::Python,
            "Flask.dispatch_request",
            "src/flask/app.py",
        );
        let base = make_method_in(
            LanguageId::Python,
            "View.dispatch_request",
            "src/flask/views.py",
        );
        for entity in [&app, &base] {
            store.upsert_entity(entity).unwrap();
        }

        let mut args = HashMap::new();
        args.insert(
            "entity_id".to_string(),
            serde_json::json!(app.id.to_string()),
        );
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        assert_eq!(body["focal_resolution"]["addressed_by"], "entity_id");
        assert_eq!(
            body["focal_resolution"]["same_name_candidates"], 1,
            "one entity carries this exact name, and the caller pinned it: {body}"
        );
        assert_eq!(
            body["focal_resolution"]["matched"], "exact_focal_name",
            "a pinned address must say it counted twins, not query matches: {body}"
        );
        assert!(
            body["degradations"]
                .as_array()
                .is_none_or(|entries| entries.iter().all(|e| e["reason"] != "ambiguous_name")),
            "a pinned address is not an ambiguous one: {body}"
        );
    }

    /// A bare name that several entities carry as their whole name is answered
    /// for each of them, never for a ranked one.
    ///
    /// A repository holding a `resolve` function in `database.rs` and another
    /// in `link_graph.rs` answered `find_references(query: "resolve")` with one
    /// of them and its reference list, and at first nothing in the response
    /// mentioned that the other existed; later it said so and still answered
    /// for one. A rename driven by it on a colliding name is a rename driven by
    /// a guess. Two unrelated free functions have no owner to label a section
    /// with, and they are sectioned by entity id and the module-qualified name
    /// that names each alone.
    #[tokio::test]
    async fn find_references_reports_an_ambiguous_name_resolution() {
        let store = InMemoryGraph::new();
        let one = make_entity("resolve", "src/database.rs");
        let two = make_entity("resolve", "src/link_graph.rs");
        store.upsert_entity(&one).unwrap();
        store.upsert_entity(&two).unwrap();

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("resolve"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        assert_eq!(body["focal_resolution"]["addressed_by"], "name");
        assert_eq!(
            body["focal_resolution"]["same_name_candidates"], 2,
            "two entities carry this name and the response must say so: {body}"
        );
        assert_eq!(body["resolution"], "same_name", "{body}");
        let mut sectioned: Vec<String> = body[AMBIGUOUS_CANDIDATES_KEY]
            .as_array()
            .unwrap_or_else(|| panic!("each entity is answered in its own section: {body}"))
            .iter()
            .map(|section| section["entity_id"].as_str().unwrap().to_string())
            .collect();
        sectioned.sort_unstable();
        let mut expected = vec![one.id.to_string(), two.id.to_string()];
        expected.sort_unstable();
        assert_eq!(sectioned, expected, "{body}");

        // Addressing the same entity by id is not ambiguous and must not
        // degrade: the caller already pinned the choice.
        let mut pinned = HashMap::new();
        pinned.insert(
            "entity_id".to_string(),
            serde_json::json!(one.id.to_string()),
        );
        let exact = parsed_response(&handle_find_references(&pinned, &store, None).await.unwrap());
        assert_eq!(exact["focal_resolution"]["addressed_by"], "entity_id");
        assert!(
            exact.get("degradations").is_none(),
            "pinning by id resolves nothing and must not degrade: {exact}"
        );
    }

    /// A bare name that only ONE owner-qualified entity carries keeps today's
    /// single-focal answer exactly as before: no sectioning, no
    /// `ambiguous_focal`, and `focal_resolution.same_name_candidates` at 1.
    ///
    /// The control for the two tests beside it. Without it, a filter bug that
    /// sectioned every owner-qualified query -- even one with nothing to
    /// disambiguate -- could not be told apart from the feature working.
    #[tokio::test]
    async fn find_references_with_one_owner_qualified_match_is_not_sectioned() {
        let store = InMemoryGraph::new();
        let target = make_method_in(
            LanguageId::Python,
            "Flask.dispatch_request",
            "src/flask/app.py",
        );
        store.upsert_entity(&target).unwrap();

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("dispatch_request"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        assert!(
            body.get("ambiguous_focal").is_none() && body.get(AMBIGUOUS_CANDIDATES_KEY).is_none(),
            "one match is not an ambiguity: {body}"
        );
        assert_eq!(
            body["focal_entity"]["name"], "Flask.dispatch_request",
            "{body}"
        );
        assert_eq!(
            body["focal_resolution"]["same_name_candidates"], 1,
            "{body}"
        );
        assert!(
            body.get("degradations").is_none(),
            "one match must not degrade: {body}"
        );
    }

    /// The core of this feature: a bare name two owner-qualified entities
    /// share answers a full, labelled section for EACH of them in one reply,
    /// with the ambiguity disclosed, rather than the resolver's single ranked
    /// winner and the other's rows nowhere in the response.
    ///
    /// Each candidate gets its own caller, deliberately different ones, so a
    /// version that merged the two candidates' rows into one undifferentiated
    /// list -- or that answered for one and left the other's callers out --
    /// fails this test where a same-shaped single-section answer would not.
    #[tokio::test]
    async fn find_references_sections_a_bare_name_two_owners_share() {
        let store = InMemoryGraph::new();
        let base = make_method_in(LanguageId::Python, "Database.resolve", "src/database.py");
        let other = make_method_in(LanguageId::Python, "LinkGraph.resolve", "src/link_graph.py");
        store.upsert_entity(&base).unwrap();
        store.upsert_entity(&other).unwrap();

        let base_caller = make_entity_in(LanguageId::Python, "load_record", "src/database.py");
        store.upsert_entity(&base_caller).unwrap();
        store
            .upsert_relation(&make_relation_with_site(
                base_caller.id,
                base.id,
                RelationKind::Calls,
                "src/database.py",
                10,
            ))
            .unwrap();

        let other_caller = make_entity_in(LanguageId::Python, "walk_edges", "src/link_graph.py");
        store.upsert_entity(&other_caller).unwrap();
        store
            .upsert_relation(&make_relation_with_site(
                other_caller.id,
                other.id,
                RelationKind::Calls,
                "src/link_graph.py",
                20,
            ))
            .unwrap();

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("resolve"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());

        assert_eq!(body["ambiguous_focal"], true, "{body}");
        assert_eq!(body["candidate_count"], 2, "{body}");
        let sections = body[AMBIGUOUS_CANDIDATES_KEY].as_array().unwrap();
        assert_eq!(sections.len(), 2, "{body}");

        let section_for = |owner_qualified_name: &str| {
            sections
                .iter()
                .find(|section| section["owner_qualified_name"] == owner_qualified_name)
                .unwrap_or_else(|| panic!("no section labelled '{owner_qualified_name}': {body}"))
        };

        let base_section = section_for("Database.resolve");
        assert_eq!(
            base_section["entity_id"],
            base.id.to_string(),
            "{base_section}"
        );
        assert_eq!(base_section["total_upstream"], 1, "{base_section}");
        let base_callers: Vec<&str> = base_section["references"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["name"].as_str().unwrap())
            .collect();
        assert_eq!(
            base_callers,
            vec!["load_record"],
            "Database.resolve's own section must carry its own caller, not the other \
             candidate's: {base_section}"
        );

        let other_section = section_for("LinkGraph.resolve");
        assert_eq!(
            other_section["entity_id"],
            other.id.to_string(),
            "{other_section}"
        );
        assert_eq!(other_section["total_upstream"], 1, "{other_section}");
        let other_callers: Vec<&str> = other_section["references"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["name"].as_str().unwrap())
            .collect();
        assert_eq!(
            other_callers,
            vec!["walk_edges"],
            "LinkGraph.resolve's own section must carry its own caller, and not \
             Database.resolve's: {other_section}"
        );

        // Neither section's own blocks are what disclose the ambiguity -- that
        // is a fact about the QUERY, not about one candidate -- so it travels
        // once, at the top, in `focal_resolution`. Every candidate was
        // answered, so it is not a degradation.
        let disclosure = &body["focal_resolution"];
        assert_eq!(disclosure["matched"], "member_name", "{disclosure}");
        assert_eq!(disclosure["sectioned"], 2, "{disclosure}");
        let detail = disclosure["detail"].as_str().unwrap();
        assert!(detail.contains("resolve"), "{detail}");
        assert!(
            detail.contains("qualified_name") && detail.contains("entity_id"),
            "the disclosure must point the caller at the remedy: {detail}"
        );
        assert!(body.get("degradations").is_none(), "{body}");
    }

    /// The pallets/flask shape the bare-name benchmark arm lost 25 points on:
    /// one owner-qualified `App.template_global` beside a substring cousin
    /// that is referenced far more. Every name-ranking term used to tie or
    /// favor the cousin, because no member's whole name is its bare name, so
    /// the query answered about `Blueprint.app_template_global`.
    #[tokio::test]
    async fn a_lone_member_name_outranks_its_substring_cousins() {
        let store = InMemoryGraph::new();
        let member = make_method_in(
            LanguageId::Python,
            "App.template_global",
            "src/flask/sansio/app.py",
        );
        let cousin = make_method_in(
            LanguageId::Python,
            "Blueprint.app_template_global",
            "src/flask/sansio/blueprints.py",
        );
        store.upsert_entity(&member).unwrap();
        store.upsert_entity(&cousin).unwrap();
        for index in 0..3 {
            let caller = make_entity_in(
                LanguageId::Python,
                &format!("caller_{index}"),
                "tests/test_templating.py",
            );
            store.upsert_entity(&caller).unwrap();
            store
                .upsert_relation(&make_relation(caller.id, cousin.id, RelationKind::Calls))
                .unwrap();
        }

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("template_global"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(
            body["focal_entity"]["name"], "App.template_global",
            "the member the bare name names must win over a cousin that only contains it: {body}"
        );
        assert!(body.get("ambiguous_focal").is_none(), "{body}");
        // The member rule settled the answer, so the resolution block counts the
        // one member it chose among, and the cousin it excluded is no ambiguity.
        assert_eq!(
            body["focal_resolution"]["same_name_candidates"], 1,
            "{body}"
        );
        assert_eq!(body["focal_resolution"]["matched"], "member_name", "{body}");
        assert!(
            body["degradations"].as_array().is_none_or(|entries| entries
                .iter()
                .all(|entry| entry["reason"] != "ambiguous_name")),
            "{body}"
        );

        let resolved =
            kin_ranking::entity_ranking::resolve_name(&store, "template_global").unwrap();
        assert!(
            matches!(&resolved, kin_ranking::entity_ranking::NameResolution::One(entity) if entity.id == member.id),
            "every single-answer surface resolves through this rule: {resolved:?}"
        );
    }

    /// The name index answers a plain name with whole-name and token matches,
    /// falls back to substrings only when it has neither, and drops a token
    /// match set over its cap. On pallets/flask that hid `Request.blueprint`
    /// behind the two `Blueprint` classes, so `blueprint` resolved to a class.
    /// The member lookup asks the index by the owner separator's suffix, which
    /// it answers whole.
    #[tokio::test]
    async fn a_member_the_name_index_hides_behind_whole_name_matches_is_still_reached() {
        let store = InMemoryGraph::new();
        let member = make_method_in(
            LanguageId::Python,
            "Request.blueprint",
            "src/flask/wrappers.py",
        );
        store.upsert_entity(&member).unwrap();
        for file in ["src/flask/blueprints.py", "src/flask/sansio/blueprints.py"] {
            let mut class = make_entity_in(LanguageId::Python, "Blueprint", file);
            class.kind = EntityKind::Class;
            store.upsert_entity(&class).unwrap();
        }
        for index in 0..40 {
            store
                .upsert_entity(&make_entity_in(
                    LanguageId::Python,
                    &format!("test_blueprint_{index}"),
                    "tests/test_blueprints.py",
                ))
                .unwrap();
        }

        // The control: the plain pattern really does leave the member out, or
        // this test would pass without the suffix lookup.
        let plain = store
            .query_entities(&kin_model::graph::EntityFilter {
                name_pattern: Some("blueprint".to_string()),
                ..Default::default()
            })
            .unwrap();
        assert!(
            plain.iter().all(|entity| entity.id != member.id),
            "control: the name index must hide the member for this fixture to mean anything"
        );

        let resolved = kin_ranking::entity_ranking::resolve_name(&store, "blueprint").unwrap();
        assert!(
            matches!(&resolved, kin_ranking::entity_ranking::NameResolution::One(entity) if entity.id == member.id),
            "{resolved:?}"
        );

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("blueprint"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert_eq!(body["focal_entity"]["name"], "Request.blueprint", "{body}");
    }

    /// Three `get` members and a substring cousin, the pallets/flask shape
    /// where `get_entity_source(entity_id: "get")` answered with the body of
    /// the tutorial's `get_db` and said nothing about the choice.
    fn shared_get_store() -> (InMemoryGraph, Vec<Entity>) {
        let store = InMemoryGraph::new();
        let scaffold = make_method_in(
            LanguageId::Python,
            "Scaffold.get",
            "src/flask/sansio/scaffold.py",
        );
        let globals = make_method_in(LanguageId::Python, "_AppCtxGlobals.get", "src/flask/ctx.py");
        let cousin = make_entity_in(LanguageId::Python, "get_db", "examples/flaskr/db.py");
        for entity in [&scaffold, &globals, &cousin] {
            store.upsert_entity(entity).unwrap();
        }
        (store, vec![globals, scaffold])
    }

    fn assert_lists_every_owner(body: &serde_json::Value, expected: &[Entity]) {
        assert_eq!(body["ambiguous_focal"], true, "{body}");
        assert_eq!(body["candidate_count"], expected.len(), "{body}");
        let candidates = body["candidates"].as_array().expect("candidates");
        let listed: Vec<(&str, &str, &str)> = candidates
            .iter()
            .map(|row| {
                (
                    row["name"].as_str().unwrap(),
                    row["owner"].as_str().unwrap(),
                    row["entity_id"].as_str().unwrap(),
                )
            })
            .collect();
        let wanted: Vec<(String, String, String)> = expected
            .iter()
            .map(|entity| {
                (
                    entity.name.clone(),
                    entity.name.split('.').next().unwrap().to_string(),
                    entity.id.to_string(),
                )
            })
            .collect();
        assert_eq!(
            listed,
            wanted
                .iter()
                .map(|(a, b, c)| (a.as_str(), b.as_str(), c.as_str()))
                .collect::<Vec<_>>(),
            "every owner's member, by file, with the id that addresses it: {body}"
        );
        assert!(
            candidates.iter().all(|row| row["member_name"] == "get"),
            "{body}"
        );
        assert!(
            body.get("body").is_none() && body.get("focal_entity").is_none(),
            "no single answer may ride beside the candidates: {body}"
        );
        assert!(
            body["degradations"]
                .as_array()
                .is_some_and(|entries| entries
                    .iter()
                    .any(|entry| entry["reason"] == "ambiguous_name")),
            "the envelope reads the ambiguity from this entry: {body}"
        );
    }

    #[test]
    fn get_entity_source_lists_every_owner_a_member_name_reaches() {
        let (store, expected) = shared_get_store();
        let mut args = HashMap::new();
        args.insert("entity_id".to_string(), serde_json::json!("get"));
        let body = parsed_response(&handle_get_entity_source(&args, &store, None).unwrap());
        assert_lists_every_owner(&body, &expected);
    }

    #[test]
    fn trace_tools_list_every_owner_a_member_name_reaches() {
        let (store, expected) = shared_get_store();

        let mut args = HashMap::new();
        args.insert("focal".to_string(), serde_json::json!("get"));
        let body = parsed_response(&handle_trace_data_flow(&args, &store).unwrap());
        assert_lists_every_owner(&body, &expected);

        let sessions = SessionRegistry::empty_for_test();
        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("get"));
        let body =
            parsed_response(&handle_trace_computation(&args, &store, &sessions, None).unwrap());
        assert_lists_every_owner(&body, &expected);
    }

    /// A `target` is a hint that steers a walk, so a shared member name there
    /// is disclosed rather than refused, and the walk still answers.
    #[test]
    fn a_shared_member_target_is_disclosed_and_the_walk_still_answers() {
        let (store, _) = shared_get_store();
        let focal = make_entity_in(LanguageId::Python, "dispatch", "src/flask/app.py");
        store.upsert_entity(&focal).unwrap();

        let mut args = HashMap::new();
        args.insert("focal".to_string(), serde_json::json!("dispatch"));
        args.insert("target".to_string(), serde_json::json!("get"));
        let body = parsed_response(&handle_trace_data_flow(&args, &store).unwrap());
        assert_eq!(body["focal_entity"]["entity_name"], "dispatch", "{body}");
        let degradations = body["degradations"].as_array().expect("degradations");
        assert!(
            degradations
                .iter()
                .any(|entry| entry["reason"] == "target_ambiguous"),
            "{body}"
        );
        assert!(
            degradations
                .iter()
                .all(|entry| entry["reason"] != "target_not_resolved"),
            "the target is in the graph, so it must not read as unresolved: {body}"
        );
        assert!(body.get("target_name").is_none(), "{body}");
    }

    /// An exact whole name is its own tier and is never pooled with members:
    /// `url_for` answers about the helper named `url_for`, not a section per
    /// `Flask.url_for` beside it, and the answer still discloses the name's
    /// other matches rather than hiding them.
    #[tokio::test]
    async fn an_exact_name_answers_ahead_of_members_that_share_it() {
        let store = InMemoryGraph::new();
        let helper = make_entity_in(LanguageId::Python, "url_for", "src/flask/helpers.py");
        let method = make_method_in(LanguageId::Python, "Flask.url_for", "src/flask/app.py");
        store.upsert_entity(&helper).unwrap();
        store.upsert_entity(&method).unwrap();

        let mut args = HashMap::new();
        args.insert("query".to_string(), serde_json::json!("url_for"));
        let body = parsed_response(&handle_find_references(&args, &store, None).await.unwrap());
        assert!(
            body.get("ambiguous_focal").is_none() && body.get(AMBIGUOUS_CANDIDATES_KEY).is_none(),
            "an exact name is not sectioned with members: {body}"
        );
        assert_eq!(
            body["focal_entity"]["id"],
            serde_json::json!(helper.id),
            "{body}"
        );
        // The member is disclosed beside the answer, and not counted as a
        // candidate the name could have resolved to: the exact tier answers
        // first, so the resolution itself is not ambiguous.
        assert_eq!(
            body["focal_resolution"]["same_name_candidates"], 1,
            "{body}"
        );
        assert_eq!(body["focal_resolution"]["matched"], "exact_name", "{body}");
        let members: Vec<&str> = body["focal_resolution"]["member_candidates"]
            .as_array()
            .unwrap_or_else(|| panic!("the member is disclosed: {body}"))
            .iter()
            .map(|row| row["name"].as_str().unwrap())
            .collect();
        assert_eq!(
            members,
            vec!["Flask.url_for"],
            "the member is disclosed: {body}"
        );

        // The same holds for a struct and an enum variant of the same name, the
        // Rust shape the review measured: the struct answers, and the variant
        // is only a fallback when nothing is named exactly.
        let store = InMemoryGraph::new();
        let mut structure = make_entity_in(LanguageId::Rust, "Entity", "src/entity.rs");
        structure.kind = EntityKind::Class;
        let mut variant = make_entity_in(LanguageId::Rust, "GraphNodeId::Entity", "src/graph.rs");
        variant.kind = EntityKind::EnumVariant;
        store.upsert_entity(&structure).unwrap();
        store.upsert_entity(&variant).unwrap();
        match kin_ranking::entity_ranking::resolve_name(&store, "Entity").unwrap() {
            kin_ranking::entity_ranking::NameResolution::One(entity) => {
                assert_eq!(entity.id, structure.id)
            }
            other => panic!("the exact name must answer: {other:?}"),
        }
    }

    /// The member contract is kind-qualified: an incidental last segment of a
    /// module or a dotted function is never a member name.
    #[test]
    fn an_incidental_last_segment_is_not_a_member_name() {
        let store = InMemoryGraph::new();
        let mut module = make_entity_in(LanguageId::Python, "app.py", "app.py");
        module.kind = EntityKind::Module;
        let dotted = make_entity_in(LanguageId::JavaScript, "exports.render", "lib/view.js");
        store.upsert_entity(&module).unwrap();
        store.upsert_entity(&dotted).unwrap();
        assert_eq!(
            kin_ranking::entity_ranking::reach_by_name(&store, "py").unwrap(),
            kin_ranking::entity_ranking::NameReach::Neither
        );
        assert_eq!(
            kin_ranking::entity_ranking::reach_by_name(&store, "render").unwrap(),
            kin_ranking::entity_ranking::NameReach::Neither
        );
    }

    /// A source read answers only a name that names one entity. A partial name
    /// used to hand back the best-ranked cousin's body and edit base: `get_d`
    /// returned `get_db`. It lists candidates now, and so do exact twins; a
    /// lone member and a single exact name still resolve, and an absent name
    /// is still not found.
    #[test]
    fn a_source_read_never_selects_a_body_by_a_partial_or_ambiguous_name() {
        let (store, _) = shared_get_store();
        let route = make_method_in(
            LanguageId::Python,
            "Scaffold.route",
            "src/flask/scaffold.py",
        );
        let twin_one = make_entity_in(LanguageId::Python, "resolve", "src/database.py");
        let twin_two = make_entity_in(LanguageId::Python, "resolve", "src/link_graph.py");
        for entity in [&route, &twin_one, &twin_two] {
            store.upsert_entity(entity).unwrap();
        }

        let source = |name: &str| {
            let mut args = HashMap::new();
            args.insert("entity_id".to_string(), serde_json::json!(name));
            handle_get_entity_source(&args, &store, None).unwrap()
        };

        let partial = parsed_response(&source("get_d"));
        assert_eq!(partial["ambiguous_focal"], true, "{partial}");
        assert_eq!(partial["resolution"], "partial_name", "{partial}");
        assert_eq!(partial["candidates"][0]["name"], "get_db", "{partial}");
        assert!(
            partial.get("body").is_none() && partial.get("source_base").is_none(),
            "a partial name must never hand back a body or an edit base: {partial}"
        );

        let twins = parsed_response(&source("resolve"));
        assert_eq!(twins["resolution"], "same_name", "{twins}");
        assert_eq!(twins["candidate_count"], 2, "{twins}");

        use kin_ranking::entity_ranking::{resolve_name_strictly, StrictNameResolution};
        assert!(matches!(
            resolve_name_strictly(&store, "route").unwrap(),
            StrictNameResolution::One(entity) if entity.id == route.id
        ));
        assert!(matches!(
            resolve_name_strictly(&store, "get_db").unwrap(),
            StrictNameResolution::One(entity) if entity.name == "get_db"
        ));
        assert!(matches!(
            resolve_name_strictly(&store, "nothing_named_this").unwrap(),
            StrictNameResolution::Missing
        ));
        let absent = source("nothing_named_this");
        assert_eq!(absent.is_error, Some(true));
    }

    /// The batch source tool lists a name's candidates in its row rather than
    /// calling the entity absent, on the offline path as on the daemon's.
    #[test]
    fn a_batch_row_for_an_ambiguous_name_lists_candidates_not_absence() {
        let (store, expected) = shared_get_store();
        let mut args = HashMap::new();
        args.insert("entity_ids".to_string(), serde_json::json!(["get"]));
        let body = parsed_response(&handle_get_entity_sources(&args, &store, None).unwrap());
        let row = &body["results"][0];
        assert_eq!(row["reason"], "ambiguous_name", "{body}");
        assert_eq!(row["resolution"], "shared_member_name", "{body}");
        assert_eq!(row["candidate_count"], expected.len(), "{body}");
        let ids: Vec<&str> = row["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .map(|candidate| candidate["entity_id"].as_str().unwrap())
            .collect();
        for entity in &expected {
            assert!(ids.contains(&entity.id.to_string().as_str()), "{body}");
        }
        assert_ne!(row["reason"], "not_found");
    }

    fn trace_ambiguity_fixture() -> (InMemoryGraph, Vec<Entity>) {
        let store = InMemoryGraph::new();
        let start = make_entity("start", "src/start.rs");
        let end = make_entity("finish", "src/end.rs");
        for entity in [&start, &end] {
            store.upsert_entity(entity).unwrap();
        }
        store
            .upsert_relation(&make_relation(start.id, end.id, RelationKind::Calls))
            .unwrap();
        let members = (0..200)
            .map(|n| {
                make_method_in(
                    LanguageId::Rust,
                    &format!("Owner界{n:03}::new"),
                    &format!("src/owner_{n:03}.rs"),
                )
            })
            .collect::<Vec<_>>();
        for member in &members {
            store.upsert_entity(member).unwrap();
        }
        (store, members)
    }

    fn assert_trace_ambiguity_count(value: &serde_json::Value, total: usize) {
        let listed = value["candidates"].as_array().map_or(0, Vec::len)
            + value["more_candidates"].as_array().map_or(0, Vec::len);
        assert_eq!(value["candidate_count"], total);
        assert_eq!(
            listed + value["omitted_candidates"].as_u64().unwrap_or(0) as usize,
            total
        );
    }

    #[tokio::test]
    async fn trace_ambiguity_focal_and_target_fit_8000_bytes_after_enveloping() {
        let (store, members) = trace_ambiguity_fixture();
        for focal in [true, false] {
            let mut args = HashMap::from([
                (
                    "focal".to_string(),
                    serde_json::json!(if focal { "new" } else { "start" }),
                ),
                ("max_response_chars".to_string(), serde_json::json!(8000)),
                ("include_body".to_string(), serde_json::json!(false)),
            ]);
            if !focal {
                args.insert("target".into(), serde_json::json!("new"));
            }
            let built = handle_trace_data_flow(&args, &store).unwrap();
            let budget = crate::budget::ResponseBudget::from_arguments(&args);
            for result in [
                built.clone(),
                crate::envelope::finalize_bounded(
                    built,
                    crate::envelope::Envelope::offline(),
                    "trace_data_flow",
                    &budget,
                ),
            ] {
                assert_ne!(result.is_error, Some(true), "{result:?}");
                let crate::ContentBlock::Text { text } = &result.content[0];
                assert!(text.len() <= 8000, "{} bytes", text.len());
                let value = parsed_response(&result);
                let listing = if focal {
                    &value
                } else {
                    &value["target_ambiguity"]
                };
                assert_trace_ambiguity_count(listing, 200);
                let ids = listing["candidates"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .chain(listing["more_candidates"].as_array().into_iter().flatten())
                    .map(|row| row["entity_id"].as_str().unwrap())
                    .collect::<Vec<_>>();
                assert!(!ids.is_empty());
                assert_eq!(
                    ids,
                    members
                        .iter()
                        .take(ids.len())
                        .map(|m| m.id.to_string())
                        .collect::<Vec<_>>()
                );
                if focal {
                    assert_eq!(value["ambiguous_focal"], true);
                    for key in [
                        "body",
                        "source_base",
                        "chain",
                        "focal_entity",
                        "bodies_included",
                    ] {
                        assert!(value.get(key).is_none(), "unexpected {key}: {value}");
                    }
                } else {
                    assert!(!value["chain"].as_array().unwrap().is_empty());
                    assert!(value.get("target_name").is_none());
                    let note = value["degradations"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .find(|d| d["reason"] == "target_ambiguous")
                        .unwrap();
                    assert_eq!(note["detail"], trace_target_detail(listing));
                }
                if value.pointer("/_kin/response/chars_after_budget").is_some() {
                    assert_eq!(value["_kin"]["response"]["chars_after_budget"], text.len());
                }
            }
        }
    }

    #[test]
    fn trace_ambiguity_equality_count_only_and_bounded_refusal_keep_totals() {
        let (_, members) = trace_ambiguity_fixture();
        let mut value = name_candidates_json(
            "trace_data_flow",
            "new",
            CandidateReason::SharedMemberName,
            &members,
        );
        assert!(fit_trace_ambiguity_payload(&mut value, 8000));
        let exact = crate::budget::measure(&value);
        let before = value.clone();
        assert!(fit_trace_ambiguity_payload(&mut value, exact));
        assert_eq!(value, before);
        assert!(fit_trace_ambiguity_payload(&mut value, exact - 1));
        assert!(crate::budget::measure(&value) < exact);
        assert_trace_ambiguity_count(&value, 200);

        let long = (0..2)
            .map(|n| {
                make_method_in(
                    LanguageId::Rust,
                    &format!("Owner{n}{}::new", "界".repeat(1000)),
                    "src/a.rs",
                )
            })
            .collect::<Vec<_>>();
        let mut count_only = name_candidates_json(
            "trace_data_flow",
            "new",
            CandidateReason::SharedMemberName,
            &long,
        );
        assert!(fit_trace_ambiguity_payload(&mut count_only, 2000));
        assert_eq!(count_only["omitted_candidates"], 2);
        assert_trace_ambiguity_count(&count_only, 2);
        assert!(crate::budget::measure(&count_only) <= 2000);

        let query = "界".repeat(5000);
        let mut refused = name_candidates_json(
            "trace_data_flow",
            &query,
            CandidateReason::SharedMemberName,
            &members,
        );
        assert!(!fit_trace_ambiguity_payload(&mut refused, 2000));
        assert!(
            !fit_trace_ambiguity_payload(&mut refused, 2000),
            "a second transport pass must preserve refusal"
        );
        assert_eq!(refused["candidate_count"], 200);
        assert_eq!(refused["omitted_candidates"], 200);
        assert!(crate::budget::measure(&refused) <= 2000);
        assert!(!crate::budget::render(&refused).unwrap().contains(&query));
    }

    #[test]
    fn trace_ambiguity_refusal_stays_bounded_after_transport_enveloping() {
        let (_, members) = trace_ambiguity_fixture();
        let query = "界".repeat(5000);
        let budget = crate::budget::ResponseBudget {
            max_chars: 2000,
            explicit_max_chars: true,
            ..Default::default()
        };
        for focal in [true, false] {
            let mut refused = if focal {
                name_candidates_json(
                    "trace_data_flow",
                    &query,
                    CandidateReason::SharedMemberName,
                    &members,
                )
            } else {
                let disclosure = target_ambiguous_degradation(
                    &query,
                    CandidateReason::SharedMemberName,
                    &members,
                );
                serde_json::json!({"target_ambiguity": trace_target_listing(&disclosure)})
            };
            assert!(!fit_trace_ambiguity_payload(&mut refused, budget.max_chars));
            assert_eq!(refused["candidate_count"], members.len());
            let mut fitting = refused.clone();
            fitting["_kin"] = serde_json::json!({"graph_as_of": "small-marker"});
            let unchanged = fitting.clone();
            assert!(!fit_trace_ambiguity_payload(&mut fitting, budget.max_chars));
            assert_eq!(fitting, unchanged, "a fitting refusal keeps its metadata");
            let mut result = ToolCallResult::error(crate::budget::render(&refused).unwrap());
            // The later transport attaches its own graph marker. It must not
            // turn an already bounded refusal into an oversized wire response.
            let mut envelope = crate::envelope::Envelope::offline();
            envelope.graph_as_of = Some(serde_json::json!({"marker": "x".repeat(4000)}));
            for _ in 0..2 {
                result = crate::envelope::finalize_bounded(
                    result,
                    envelope.clone(),
                    "trace_data_flow",
                    &budget,
                );
                assert_eq!(result.is_error, Some(true));
                let crate::ContentBlock::Text { text } = &result.content[0];
                assert!(
                    text.len() <= budget.max_chars,
                    "{} bytes: {text}",
                    text.len()
                );
                let value = parsed_response(&result);
                assert_eq!(value["ambiguous_focal"], focal);
                assert_eq!(value["ambiguous_target"], !focal);
                assert_eq!(value["candidate_count"], members.len());
                assert_eq!(value["omitted_candidates"], members.len());
                assert_eq!(value["resolution"], "shared_member_name");
                assert_eq!(value["error"], refused["error"]);
                assert!(!text.contains(&query));
                for key in ["body", "source_base", "chain", "focal_entity"] {
                    assert!(value.get(key).is_none(), "unexpected {key}: {value}");
                }
            }
        }
    }

    /// No candidate vanishes past a cap: past the detailed rows each is listed
    /// by id, and past the listing the answer says how many it left out.
    #[test]
    fn every_capped_candidate_list_names_or_counts_the_rest() {
        let candidates: Vec<Entity> = (0..230)
            .map(|index| {
                make_method_in(
                    LanguageId::Rust,
                    &format!("Owner{index:03}::new"),
                    &format!("src/owner_{index:03}.rs"),
                )
            })
            .collect();
        let value = name_candidates_json(
            "get_entity_source",
            "new",
            kin_ranking::entity_ranking::CandidateReason::SharedMemberName,
            &candidates,
        );
        assert_eq!(value["candidate_count"], 230);
        assert_eq!(value["candidates"].as_array().unwrap().len(), 25);
        let more = value["more_candidates"].as_array().unwrap();
        assert_eq!(more.len(), 175);
        assert!(more.iter().all(|row| row["entity_id"].is_string()));
        assert_eq!(value["omitted_candidates"], 30);
        let detail = value["degradations"][0]["detail"].as_str().unwrap();
        assert!(detail.contains("30 more are not listed"), "{detail}");

        let lines = name_candidates_lines(
            "new",
            kin_ranking::entity_ranking::CandidateReason::SharedMemberName,
            &candidates,
        );
        assert!(
            lines.iter().any(|line| line.contains("... and 30 more")),
            "{lines:?}"
        );
        assert!(
            lines
                .iter()
                .any(|line| line.contains(&candidates[199].id.to_string())),
            "the last listed candidate carries its id"
        );
    }

